document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll("a[href]").forEach(function(e){const t=e.getAttribute("href");if(!t||t.startsWith("#")||t.startsWith("javascript:")||t.startsWith("mailto:")||t.startsWith("tel:"))return;let r;try{r=new URL(e.href,document.baseURI)}catch{return}if(!(r.origin!==window.location.origin)||e.getAttribute("target")==="_self")return;e.setAttribute("target","_blank");const i=e.getAttribute("rel")||"",n=new Set(i.split(/\s+/).filter(Boolean));n.add("noopener"),n.add("noreferrer"),e.setAttribute("rel",Array.from(n).join(" "))})}),document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll('a[href^="#"]').forEach(function(o){o.addEventListener("click",function(e){const t=this.getAttribute("href")||"";if(t==="#"||t.toLowerCase()==="#top"){e.preventDefault(),window.scrollTo(0,0);return}if(t.length>1)try{const r=document.querySelector(t);r&&(e.preventDefault(),r.scrollIntoView({behavior:"smooth",block:"start"}))}catch{}})})});
